import {PRODUCTS,PALETTE,ALIASES,defaults,color,validSelection} from './products.js';
import {setupCartBridge} from './cart-bridge.js';
const $=selector=>document.querySelector(selector),dialog=$('#product-dialog'),storageKey='ju.colors.v1';
let saved={};try{saved=JSON.parse(localStorage.getItem(storageKey)||'{}')||{};}catch{}
const selections=Object.fromEntries(Object.keys(PRODUCTS).map(key=>[key,validSelection(key,saved[key])]));
let activeProduct=null,selectedPart='body',view='photo',viewer=null,viewerImport=null,request=0,canStore=true;
function save(){try{localStorage.setItem(storageKey,JSON.stringify(selections));canStore=true;}catch{canStore=false;}}
function hexColors(){return Object.fromEntries(Object.entries(selections[activeProduct]).map(([id,value])=>[id,color(value).hex]));}
function setMode(next){$('#product-info').hidden=next!=='info';$('#customizer').hidden=next!=='custom';$('#combination').hidden=next!=='summary';dialog.dataset.mode=next;$('#personalize').hidden=next!=='info';$('#finish').hidden=next!=='custom';$('#edit-colors').hidden=next!=='summary';dialog.scrollTop=0;$('.detail-copy').scrollTop=0;}
function announce(message){$('#color-announcement').textContent=message;}
function fillProduct(key){const p=PRODUCTS[key];$('#dialog-number').textContent=`COLEÇÃO 01 / PEÇA ${p.number}`;$('#dialog-title').textContent=p.title;$('#dialog-subtitle').textContent=p.subtitle;$('#dialog-description').textContent=p.description;$('#dialog-image').src=`assets/${p.image}`;$('#dialog-image').alt=`${p.title} sobre uma pilastra branca — imagem de apresentação`;$('#fixed-note').textContent=p.fixed;document.title=`${p.title} | Ju imprime pra mim`;}
function syncProduct(){const [raw,step]=location.hash.replace('#produto/','').split('/'),key=ALIASES[raw]||raw;if(!PRODUCTS[key]){if(dialog.open)dialog.close();document.title='Ju imprime pra mim • Coleção 3D';return;}const changed=key!==activeProduct||!dialog.open;activeProduct=key;fillProduct(key);if(changed){selectedPart='body';setMode('info');}if(!dialog.open)dialog.showModal();lockPage();if(step==='personalizar'){if(changed||dialog.dataset.mode==='info')personalize();}else if(changed)setView('photo');}
let lockedScroll=null;
function lockPage(){if(lockedScroll!==null)return;lockedScroll=window.scrollY;document.documentElement.classList.add('modal-open');Object.assign(document.body.style,{position:'fixed',top:`-${lockedScroll}px`,width:'100%',overflow:'hidden'});}
function unlockPage(){if(lockedScroll===null)return;const y=lockedScroll;lockedScroll=null;document.documentElement.classList.remove('modal-open');Object.assign(document.body.style,{position:'',top:'',width:'',overflow:''});window.scrollTo(0,y);}
function closeProduct(){history.replaceState(null,'',location.pathname+location.search);dialog.close();document.title='Ju imprime pra mim • Coleção 3D';}
function viewerError(){const msg=$('.viewer-message');msg.hidden=false;msg.textContent='A prévia 3D não está disponível neste navegador. Você pode continuar escolhendo as cores e consultar a imagem do produto.';$('.viewer-tools').hidden=true;viewer?.dispose();viewer=null;}
async function setView(next){view=next;const id=++request;document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===next)));$('.image-area').hidden=next!=='photo';$('#viewer-host').hidden=next!=='model';$('.viewer-tools').hidden=true;$('.viewer-message').hidden=true;$('.view-note').textContent=next==='photo'?'Imagem de apresentação • cores originais.':'Arraste para girar · Prévia 3D ilustrativa, aguardando os modelos finais.';if(next==='photo'){viewer?.hide();return;}$('.viewer-message').hidden=false;$('.viewer-message').textContent='Preparando sua prévia 3D…';try{viewerImport??=import('./viewer.js');const {ProductViewer}=await viewerImport;if(id!==request||!dialog.open||view!=='model')return;viewer??=new ProductViewer($('#viewer-host'),viewerError);viewer.show(activeProduct,hexColors(),PRODUCTS[activeProduct].title);$('.viewer-message').hidden=true;$('.viewer-tools').hidden=false;}catch(error){console.error('Visualização 3D indisponível:',error);if(id===request)viewerError();}}
function renderControls(){const p=PRODUCTS[activeProduct];$('#part-tabs').replaceChildren(...p.parts.map(part=>{const b=document.createElement('button');b.type='button';b.dataset.part=part.id;b.innerHTML='<span class="part-dot" aria-hidden="true"></span><span></span>';b.lastElementChild.textContent=part.name;return b;}));$('#palette').replaceChildren(...PALETTE.map(value=>{const b=document.createElement('button');b.type='button';b.className='swatch';b.dataset.color=value.id;b.style.setProperty('--swatch',value.hex);b.style.setProperty('--check',['yellow','cream','mint','white'].includes(value.id)?'#332b32':'#fff');b.setAttribute('aria-label',value.name);const swatch=document.createElement('i');swatch.setAttribute('aria-hidden','true');const label=document.createElement('span');label.textContent=value.name;b.append(swatch,label);return b;}));updateControls();}
function updateControls(){const s=selections[activeProduct],p=PRODUCTS[activeProduct];document.querySelectorAll('[data-part]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.part===selectedPart));b.querySelector('.part-dot').style.background=color(s[b.dataset.part]).hex;});document.querySelectorAll('[data-color]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.color===s[selectedPart])));$('#selected-color').textContent=color(s[selectedPart]).name;$('#part-hint').textContent=p.parts.find(part=>part.id===selectedPart).hint;viewer?.update(hexColors());}
function personalize(){setMode('custom');renderControls();setView('model');}
function summary(){setMode('summary');save();const p=PRODUCTS[activeProduct];$('#combination-list').replaceChildren(...p.parts.map(part=>{const li=document.createElement('li'),dot=document.createElement('i'),text=document.createElement('span'),name=document.createElement('strong'),value=document.createElement('small'),selected=color(selections[activeProduct][part.id]);dot.style.background=selected.hex;dot.setAttribute('aria-hidden','true');name.textContent=part.name;value.textContent=selected.name;text.append(name,value);li.append(dot,text);return li;}));$('.saved-note').textContent=canStore?'Suas cores estão salvas neste navegador.':'Sua combinação está pronta nesta sessão.';$('#edit-colors').focus({preventScroll:true});}
$('.close').addEventListener('click',closeProduct);$('.back').addEventListener('click',closeProduct);dialog.addEventListener('cancel',e=>{e.preventDefault();closeProduct();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeProduct();}});dialog.addEventListener('close',()=>{++request;viewer?.hide();unlockPage();document.querySelector(`[data-product="${activeProduct}"]`)?.focus({preventScroll:true});});
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
$('#personalize').addEventListener('click',personalize);$('#edit-colors').addEventListener('click',personalize);$('#back-info').addEventListener('click',()=>{setMode('info');$('#personalize').focus({preventScroll:true});});
$('#part-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-part]');if(!b)return;selectedPart=b.dataset.part;updateControls();});
$('#palette').addEventListener('click',e=>{const b=e.target.closest('[data-color]');if(!b)return;selections[activeProduct][selectedPart]=b.dataset.color;updateControls();save();announce(`${PRODUCTS[activeProduct].parts.find(p=>p.id===selectedPart).name}: ${color(b.dataset.color).name}.`);});
$('#reset-colors').addEventListener('click',()=>{selections[activeProduct]=defaults(activeProduct);updateControls();save();announce('Cores originais restauradas para este produto.');});$('#finish').addEventListener('click',summary);
$('#copy-combination').addEventListener('click',async()=>{const p=PRODUCTS[activeProduct],text=`${p.title} — minha combinação\n`+p.parts.map(part=>`${part.name}: ${color(selections[activeProduct][part.id]).name}`).join('\n');try{await navigator.clipboard.writeText(text);$('.saved-note').textContent='Combinação copiada!';}catch{$('.saved-note').textContent='Não foi possível copiar automaticamente. As cores estão listadas acima.';}});
document.querySelectorAll('[data-camera]').forEach(b=>b.addEventListener('click',()=>{if(!viewer)return;const a=b.dataset.camera;if(a==='left'||a==='right')viewer.rotate(a==='left'?-1:1);else if(a==='in'||a==='out')viewer.zoom(a==='in'?1:-1);else if(a==='reset')viewer.reset();else{const auto=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(auto));b.textContent=auto?'Pausar':'Girar';b.setAttribute('aria-label',auto?'Pausar giro automático':'Girar automaticamente');viewer.setAuto(auto);}}));
window.addEventListener('hashchange',syncProduct);window.addEventListener('pagehide',()=>viewer?.hide());syncProduct();
setupCartBridge({getProduct:()=>activeProduct,getSelection:()=>({...selections[activeProduct]}),capture:()=>{try{return view==='model'&&viewer?.key===activeProduct?viewer.snapshot():null;}catch{return null;}},restore:selection=>{selections[activeProduct]=validSelection(activeProduct,selection);personalize();}});

